c.cpp:
class Solution {
public:
    int sumOfEncryptedInt(vector<int>& nums) {
        int ans = 0;
        for (int x : nums) {
            int d = 0, len = 0, rep = 0;
            while (x) { d = max(d, x % 10); x /= 10; rep = rep * 10 + 1; len++; }
            ans += d * rep;
        }
        return ans;
    }
};

c.java:
class Solution {
    public int sumOfEncryptedInt(int[] nums) {
        int ans = 0;
        for (int x : nums) {
            int d = 0, rep = 0;
            while (x > 0) { d = Math.max(d, x % 10); x /= 10; rep = rep * 10 + 1; }
            ans += d * rep;
        }
        return ans;
    }
}

